"use client";
import { useEffect, useState } from "react";
import { AnimatedCircularProgressBar } from "@/components/huemo/magicui/ui/animated-circular-progress-bar";
const step = (prev: number) => (prev >= 100 ? 0 : prev + 10);
export default function Example() {
    const gaugeSecondaryColor = (__HUEMO_PROP_gaugeSecondaryColor__ as string);
    const [value, setValue] = useState(0);
    useEffect(() => {
        const first = setTimeout(() => setValue(step), 0);
        const interval = setInterval(() => setValue(step), 2000);
        return () => {
            clearTimeout(first);
            clearInterval(interval);
        };
    }, []);
    return (<button type="button" aria-label={"Advance progress"} className="cursor-pointer rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring" onClick={() => {
            setValue(step);
        }}>
      <AnimatedCircularProgressBar value={value} gaugePrimaryColor={__HUEMO_PROP_gaugePrimaryColor__} gaugeSecondaryColor={(gaugeSecondaryColor ?? "#333333")}/>
    </button>);
}

